Team lead asked me to sanity-check this new test file someone added for our date-formatting util before we merge. Worth a look?

```ts
import { describe, it, expect, vi } from "vitest";
import { formatRelativeTime } from "../src/format-relative-time";

describe("formatRelativeTime", () => {
  it("matches snapshot for a recent timestamp", () => {
    const result = formatRelativeTime(Date.now() - 5000);
    expect(result).toMatchSnapshot();
  });

  it("matches snapshot for an old timestamp", () => {
    const result = formatRelativeTime(new Date("2020-01-01").getTime());
    expect(result).toMatchSnapshot();
  });

  it.concurrent("formats several timestamps without cross-contamination", async () => {
    const cache = formatRelativeTime.__cache; // module-level memoization cache exposed for testing
    cache.clear();
    const a = await Promise.resolve(formatRelativeTime(Date.now() - 1000));
    expect(cache.size).toBe(1);
  });

  it.concurrent("caches repeated calls for the same minute bucket", async () => {
    const cache = formatRelativeTime.__cache;
    cache.clear();
    formatRelativeTime(Date.now() - 2000);
    formatRelativeTime(Date.now() - 2000);
    expect(cache.size).toBe(1);
  });

  it("returns a string", () => {
    const result = formatRelativeTime(Date.now() - 60000);
    expect(typeof result).toBe("string");
  });
});
```

